# owner: platform
"""Seating charts: students sorted by last name and split into rows."""

from typing import List

from rosterkit.models import Student

def _format_name(student: Student) -> str:
    return f"{student.last_name}, {student.first_name}"

def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())

def _chunked(names: List[str], size: int) -> List[List[str]]:
    return [names[start:start + size] for start in range(0, len(names), size)]

# ---
def seating_rows(students: List[Student], seats_per_row: int) -> List[str]:
    """One line of text per row, students sorted by last name."""
    if seats_per_row <= 0:
        raise ValueError("seats_per_row must be positive")
    if not students:
        raise ValueError("no students to seat")
    names = [_format_name(item) for item in sorted(students, key=_sort_key)]
    rows = _chunked(names, seats_per_row)
    return [f"Row {index}: {' | '.join(row)}" for index, row in enumerate(rows, 1)]

