# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows

def _student(last, first):
    return Student("id", last, first, "A")

class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [_student("Halloway", "Juno"), _student("Dunmere", "Piet"), _student("Abel", "Zoe")]
        expected = ["Row 1: Abel, Zoe | Dunmere, Piet", "Row 2: Halloway, Juno"]
        self.assertEqual(seating_rows(people, 2), expected)

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows([_student("Abel", "Zoe")], seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
